import { createFileRoute, redirect } from "@tanstack/react-router";
import { pageHead } from "@/utils/page-head";

// ##################
// authored (generated by antigravity, Jun 24 2026 21:18 WITA)
// ##################

export const Route = createFileRoute(
  "/(core)/pelatihan/belajar/$enrollmentId/",
)({
  loader: async ({ context, params }) => {
    try {
      const enrollment = await context.queryClient.ensureQueryData(
        context.trpc.pelatihan.enrollment.getUserEnrollmentById.queryOptions({
          id: params.enrollmentId,
        }),
      );

      // Check for pre-test first
      const assessments = enrollment.pelatihan?.assessments ?? [];
      const preTest = assessments.find((a) => a.type === "pre_test");

      if (preTest) {
        // Fetch assessment attempts to check if pre-test is passed
        const assessmentDataList = await context.queryClient.ensureQueryData(
          context.trpc.pelatihan.assessment.getAssessmentsByPelatihanId.queryOptions(
            {
              pelatihanId: enrollment.pelatihanId,
              enrollmentId: params.enrollmentId,
            },
          ),
        );

        const preTestData = assessmentDataList.find((a) => a.id === preTest.id);

        const hasCompletedPreTest =
          preTestData?.latestAttemptStatus &&
          ["submitted", "graded", "reviewed"].includes(
            preTestData.latestAttemptStatus,
          );

        // If pre-test exists and hasn't been completed, redirect to it
        if (!hasCompletedPreTest) {
          throw redirect({
            to: "/pelatihan/belajar/$enrollmentId/ujian/$assessmentId",
            params: {
              enrollmentId: params.enrollmentId,
              assessmentId: preTest.id,
            },
          });
        }
      }

      const materials = enrollment.pelatihan?.materials ?? [];
      const progresses = enrollment.progresses ?? [];

      if (materials.length === 0) {
        // Handle no materials case by not redirecting (showing an empty state component)
        return { materials: [] };
      }

      // Calculate which material is currently unlocked
      const completedMaterialIds = new Set(
        progresses
          .filter((p) => p.completed && p.materialId)
          .map((p) => p.materialId),
      );

      let firstUncompletedIndex = materials.findIndex(
        (m) => !completedMaterialIds.has(m.id),
      );

      if (firstUncompletedIndex === -1) {
        firstUncompletedIndex = materials.length - 1; // All completed, go to last
      }

      const targetMaterialId = materials[firstUncompletedIndex]?.id;

      if (targetMaterialId) {
        throw redirect({
          to: "/pelatihan/belajar/$enrollmentId/materi/$materiId",
          params: {
            enrollmentId: params.enrollmentId,
            materiId: targetMaterialId,
          },
        });
      }

      return { materials };
    } catch (error) {
      if (error && typeof error === "object" && "isRedirect" in error) {
        throw error;
      }
      throw redirect({ to: "/pelatihan/transaksi" });
    }
  },
  head: () => pageHead("Pelatihan - Belajar"),
  component: BelajarIndexComponent,
});

function BelajarIndexComponent() {
  return (
    <div className="flex h-full items-center justify-center p-8">
      <div className="space-y-2 text-center">
        <h2 className="text-2xl font-bold tracking-tight">Belum Ada Materi</h2>
        <p className="text-muted-foreground">
          Pelatihan ini belum memiliki materi untuk dipelajari.
        </p>
      </div>
    </div>
  );
}
